// Prompt: Write void add_score(int table[5], int score).
// Keep it sorted high to low. If score beats an entry, insert it and drop the lowest.
// Claude’s answer:
void add_score(int table[5], int score) {
    for (int i = 0; i < 5; i++) {
        if (score > table[i]) {
            for (int j = 5; j > i; j--) {
                table[j] = table[j - 1];
            }
            table[i] = score;
            return;
        }
    }
}

