// Prompt: Write check_guess for my guessing game.
// Claude’s answer:
typedef enum { TOO_LOW, TOO_HIGH, CORRECT } Verdict;
typedef void (*ResultCallback)(Verdict v);

typedef struct {
    Verdict verdict;
    ResultCallback on_result;
} GuessResult;

GuessResult *check_guess(int guess, int secret, ResultCallback cb) {
    GuessResult *r = malloc(sizeof(GuessResult));
    if (guess < secret) r->verdict = TOO_LOW;
    else if (guess > secret) r->verdict = TOO_HIGH;
    else r->verdict = CORRECT;
    r->on_result = cb;
    cb(r->verdict);
    return r;
}

// What you needed:
int check_guess(int guess, int secret) {
    if (guess < secret) return -1;
    if (guess > secret) return 1;
    return 0;
}

